<?php elseif($tab==='profile'): ?><div class="panel"><div class="panel-head"><div><span class="eyebrow">PUBLISHER ACCOUNT</span><h3>Publisher profile</h3><p>Keep your contact and organization details current for campaign communication.</p></div></div><div class="panel-body"><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="update_profile"><div class="field"><label>First name</label><input name="first_name" value="<?=e($user['first_name'])?>" required maxlength="80"></div><div class="field"><label>Last name</label><input name="last_name" value="<?=e($user['last_name'])?>" required maxlength="80"></div><div class="field"><label>Email address</label><input value="<?=e($user['email'])?>" disabled></div><div class="field"><label>Mobile number</label><input name="phone" value="<?=e($user['phone'])?>" inputmode="tel" placeholder="+880..."></div><div class="field"><label>Country</label><input name="country" value="<?=e($user['country']?:'Bangladesh')?>" required maxlength="100"></div><div class="field"><label>District / Region</label><input name="district" value="<?=e($user['district'])?>" maxlength="100"></div><div class="field"><label>City</label><input name="city" value="<?=e($user['city'])?>" maxlength="120"></div><div class="field"><label>Occupation</label><input name="occupation" value="<?=e($user['occupation'])?>" maxlength="120"></div><div class="field full"><label>Organization / Company</label><input name="organization" value="<?=e($user['organization'])?>" maxlength="180"></div><div class="field full"><label>Website / Portfolio</label><input type="url" name="website" value="<?=e($user['website'])?>" placeholder="https://example.com"></div><div class="field full"><label>Skills and interests</label><textarea name="skills" maxlength="2000" rows="3"><?=e($user['skills'])?></textarea></div><div class="field full"><button class="btn" type="submit">Save publisher profile</button></div></form></div></div><?php endif; ?>

<?php else: require __DIR__.'/dashboard/admin.php'; ?>
<?php endif; ?>
</div></div></div></section>
